{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "In humans, racemic verapamil—the closest analogue (Morgan 0.4179)—had an absolute oral bioavailability of 16%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Verapamil absolute oral bioavailability was 19.25% in normal subjects after an 80 mg oral dose, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Verapamil bioavailability was reported as 12% in patients, clearly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "S-verapamil mean oral bioavailability was 10.5% in humans, below 20%, and the query is achiral with a verapamil-like backbone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "R-verapamil showed 67% oral bioavailability in humans, above 20%, but this enantiomer-specific high value is less transferable to the achiral query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Gallopamil, a trimethoxy verapamil analogue, showed 96.3% bioavailability in humans, above 20%, but it lacks the query's highly polar cyclic disulfone and is less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a verapamil-like tertiary amine with a highly polar cyclic disulfone replacing the nitrile/isopropyl group. Closest experimental analogues (verapamil, Morgan ~0.42) show human absolute oral bioavailability clustered around or below 20% (e.g., 16%, 19.25%, 12%, 10.5%), and the added disulfone increases TPSA and molecular weight while the basic amine remains mostly ionized at intestinal pH, supporting F<20%. Higher-F analogues such as R-verapamil and gallopamil are less transferable due to stereochemical or structural differences.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the query molecule.",
    "The effect of the cyclic disulfone moiety on permeability, solubility, and first-pass metabolism is not directly represented in the evidence set.",
    "Verapamil bioavailability varies with formulation, enantiomer, and study conditions, adding uncertainty to threshold classification."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

